-- State transitions declared for WorkOrder: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION manufacturing.work_orders_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('confirmed', 'cancel'), ('confirmed', 'done'), ('confirmed', 'progress'), ('draft', 'cancel'), ('draft', 'confirmed'), ('progress', 'done'), ('progress', 'to_close'), ('to_close', 'done'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: work_orders.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_work_orders__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS work_orders_status_transition_check ON manufacturing.work_orders;
CREATE TRIGGER work_orders_status_transition_check
    BEFORE UPDATE OF "status" ON manufacturing.work_orders
    FOR EACH ROW EXECUTE FUNCTION manufacturing.work_orders_status_transition_check();
